/**
 * Full Delhi Metro network data pack v1 — offline bundle.
 * Raw data generated by tools/data-prep/build-network.mjs (do not edit that file).
 * Adapted here into the NetworkData shape the graph/planner consume.
 */
import generated from './delhiNetwork.g';
import type { NetworkData, LineDef, StationDef } from './data';

type RawStation = {
  id: string;
  name: string;
  lat?: number;
  lon?: number;
  toNextS?: number;
};

type RawLine = {
  id: string;
  name: string;
  color: string;
  segments: { id: string; stations: RawStation[] }[];
};

const raw = generated as unknown as {
  generatedAt: string;
  lines: RawLine[];
};

/** Line colors for UI (GraphVarLineDef has none in the shared type). */
export const LINE_COLORS: Record<string, string> = Object.fromEntries(
  raw.lines.map((l) => [l.id, l.color]),
);

const lines: LineDef[] = raw.lines.map((line) => ({
  id: line.id,
  name: line.name,
  segments: line.segments.map((seg) => ({
    id: seg.id,
    stations: seg.stations.map(
      (st): StationDef => ({
        id: st.id,
        name: st.name,
        lat: st.lat,
        lon: st.lon,
        toNextS: st.toNextS,
      }),
    ),
  })),
}));

export const generatedAt: string = raw.generatedAt;

export const delhiNetwork: NetworkData = {
  transferPenaltyS: 300,
  sameLineBranchPenaltyS: 0,
  lines,
};

export { collectStations, collectStationsWithCoords } from './data';
